#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.selfDamage)]
    public class SelfDamageBehaviour : EntityBehaviourDefinition
    {
        public SelfDamageBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            var interval = entity.GetProperty<int>(PROP_DAMAGE_INTERVAL);
            if (entity.IsTimeInterval(interval))
            {
                var effects = new DamageEffectList(VanillaDamageEffects.SELF_DAMAGE, VanillaDamageEffects.IGNORE_ARMOR);
                entity.TakeDamage(entity.GetProperty<float>(PROP_DAMAGE_AMOUNT), effects, entity);
            }
        }
        public static readonly VanillaEntityPropertyMeta<int> PROP_DAMAGE_INTERVAL = new VanillaEntityPropertyMeta<int>("damage_interval", 30);
        public static readonly VanillaEntityPropertyMeta<float> PROP_DAMAGE_AMOUNT = new VanillaEntityPropertyMeta<float>("damage_amount", 100f);
    }
}
